#!/usr/bin/env bash
set -euo pipefail

# Translation/error message fixes v2 for Baruda.
# Run this from the baruda project root OR from the folder that contains baruda/.

if [[ -f "package.json" && -d "components" && -d "lib/i18n" ]]; then
  PROJECT_ROOT="$(pwd)"
elif [[ -d "baruda" && -f "baruda/package.json" ]]; then
  PROJECT_ROOT="$(pwd)/baruda"
else
  echo "ERROR: Could not find the Baruda project root."
  echo "Run this script from the project root or from the folder that contains baruda/."
  exit 1
fi

cd "$PROJECT_ROOT"

BACKUP_DIR=".patch-backups/translation-error-message-fixes-v2-$(date +%Y%m%d_%H%M%S)"
mkdir -p "$BACKUP_DIR"

FILES=(
  "lib/i18n/translations.ts"
  "lib/i18n/apiErrorMessages.ts"
  "components/SubmitNumberModal.tsx"
  "components/ReceiptUploader.tsx"
  "components/ManageNumbersPanel.tsx"
  "components/AdminNumbersPanel.tsx"
)

for file in "${FILES[@]}"; do
  if [[ -f "$file" ]]; then
    mkdir -p "$BACKUP_DIR/$(dirname "$file")"
    cp "$file" "$BACKUP_DIR/$file"
  fi
done

TMP_PAYLOAD="$(mktemp -d)"
cleanup() { rm -rf "$TMP_PAYLOAD"; }
trap cleanup EXIT

base64 -d > "$TMP_PAYLOAD/payload.tgz" <<'PAYLOAD_EOF'

PAYLOAD_EOF

tar -xzf "$TMP_PAYLOAD/payload.tgz" -C "$PROJECT_ROOT"

echo "✅ Translation/error-message fixes v2 applied."
echo "📦 Backup saved at: $BACKUP_DIR"
echo ""
echo "Next steps:"
echo "  npm run dev"
echo "  npm run build"
echo ""
echo "Test these flows in English, Amharic, and Oromifa:"
echo "  - Submit number modal reservation/validation errors"
echo "  - Receipt upload errors"
echo "  - Manage numbers close/reopen/update target errors"
echo "  - Dashboard announcement image upload errors"
